export type AnchorStatus =
  | { kind: 'unanchored' }
  | { kind: 'matched' }
  | { kind: 'shifted'; startLine: number; endLine: number }
  | { kind: 'stale'; reason: 'notFound' | 'ambiguous' | 'fileMissing' };

